#![forbid(unsafe_code)]
//! Messages generated by only-protobuf-build from `proto/`, for the tests, the grpc-go interop
//! example and the prost comparison benchmark.

/// `test.*` packages.
pub mod test {
    /// `test.all`.
    pub mod all {
        only_protobuf::include_proto!("test.all");
    }
    /// `test.common`.
    pub mod common {
        only_protobuf::include_proto!("test.common");
    }
    /// `test.p2` (proto2).
    pub mod p2 {
        only_protobuf::include_proto!("test.p2");
    }
    /// `test.ext` (proto2 groups and extensions).
    pub mod ext {
        only_protobuf::include_proto!("test.ext");
    }
    /// `test.ed` (edition 2024).
    pub mod ed {
        only_protobuf::include_proto!("test.ed");
    }
    /// `test.utf8` (`utf8_validation = NONE` on single fields, edition 2023).
    pub mod utf8 {
        only_protobuf::include_proto!("test.utf8");
    }
    /// `test.utf8f` (`utf8_validation = NONE` for a whole file).
    pub mod utf8f {
        only_protobuf::include_proto!("test.utf8f");
    }
    /// `test.utf8p2` (proto2 strings compiled with `proto2_unchecked_strings`).
    pub mod utf8p2 {
        only_protobuf::include_proto!("test.utf8p2");
    }
    /// `test.btree` (BTreeMap maps, no unknown fields).
    pub mod btree {
        only_protobuf::include_proto!("test.btree");
    }
}

/// grpc-go's route_guide example.
pub mod routeguide {
    only_protobuf::include_proto!("routeguide");
}

/// grpc-go's helloworld example.
pub mod helloworld {
    only_protobuf::include_proto!("helloworld");
}

/// The conformance suite's messages.
pub mod conformance {
    only_protobuf::include_proto!("conformance");
}

/// The conformance suite's test messages.
pub mod protobuf_test_messages {
    /// proto2.
    pub mod proto2 {
        only_protobuf::include_proto!("protobuf_test_messages.proto2");
    }
    /// proto3.
    pub mod proto3 {
        only_protobuf::include_proto!("protobuf_test_messages.proto3");
    }
    /// Edition 2023.
    pub mod editions {
        only_protobuf::include_proto!("protobuf_test_messages.editions");
        /// proto2 semantics in edition 2023.
        pub mod proto2 {
            only_protobuf::include_proto!("protobuf_test_messages.editions.proto2");
        }
        /// proto3 semantics in edition 2023.
        pub mod proto3 {
            only_protobuf::include_proto!("protobuf_test_messages.editions.proto3");
        }
    }
}

pub mod service;
